-- Abwehr — 14 моделей. Оновлює описи, не змінює наявні фото та характеристики.
-- Фото й технічні дані для цих моделей уже внесені попередніми пакетами Abwehr.

update public.products as product
set description = source.description
from (values
  ('catalog-1', 'Abwehr Harmonia — сучасні вхідні двері для квартири з комплектацією Megapolis Kale. Посилена сталева конструкція, МДФ-накладки та мінеральна вата допомагають забезпечити безпеку, тепло і тишу.'),
  ('catalog-2', 'Abwehr Limana — квартирні вхідні двері комплектації Megapolis Kale. Полотно 100 мм, метал 1,5 мм, мінеральна вата й чотири ребра жорсткості створюють надійне рішення для оселі.'),
  ('catalog-3', 'Abwehr Melany — сучасні вхідні двері для квартири у комплектації Megapolis MG3. Полотно 100 мм, мінеральна вата та МДФ-накладки поєднують комфорт, дизайн і захист.'),
  ('catalog-4', 'Abwehr Mira — вхідні двері для квартири комплектації Megapolis Kale. Сталева конструкція, полотно 100 мм, МДФ-накладки і мінеральна вата допомагають зберігати тишу та тепло.'),
  ('catalog-5', 'Abwehr Rain — квартирні вхідні двері комплектації Classic Prime. Полотно 100 мм, метал 1,5 мм і мінеральна вата створюють надійний захист та комфорт у щоденному користуванні.'),
  ('catalog-6', 'Abwehr Riviera — сучасні вхідні двері для квартири у комплектації Megapolis Kale. Конструкція з полотном 100 мм, МДФ-накладками і мінеральною ватою забезпечує практичність та комфорт.'),
  ('catalog-7', 'Abwehr Selena — квартирні вхідні двері комплектації Megapolis MG3. Сталеве полотно 100 мм, МДФ-накладки та мінеральна вата поєднують сучасний вигляд і захисні властивості.'),
  ('catalog-8', 'Abwehr Stella — посилені вхідні двері для квартири комплектації Grand. Полотно 115 мм, сім ребер жорсткості, мінеральна вата та замки Securemme створюють високий рівень захисту.'),
  ('catalog-9', 'Abwehr Avenue — вуличні вхідні двері комплектації Termix із терморозривом у коробі та полотні. Багатошарове утеплення допомагає зберігати тепло в приватному будинку.'),
  ('catalog-10', 'Abwehr Carat — вуличні двері Termix із терморозривом і енергоефективним дзеркальним склопакетом. Практичний варіант для приватного будинку з акцентом на теплоізоляцію.'),
  ('catalog-11', 'Abwehr Queen — вуличні двері комплектації Bionica Combo з терморозривом, трьома контурами ущільнення та енергоефективним склопакетом. Створені для тепла й надійності.'),
  ('catalog-12', 'Abwehr Revolution — вуличні вхідні двері Termix із терморозривом у коробі та полотні. Тришарове утеплення, МДФ-накладка і надійні замки забезпечують комфортний вхід до будинку.'),
  ('catalog-13', 'Abwehr Tower 1200 — полуторні вуличні двері Termix для широкого отвору. Терморозрив, тришарове утеплення і чотири антизрізи допомагають забезпечити тепло та захист.'),
  ('catalog-14', 'Abwehr Tower — вуличні двері Termix із терморозривом, тришаровим утепленням та енергоефективним склопакетом. Надійне рішення для входу в приватний будинок.')
) as source(slug, description)
where product.slug = source.slug;
